-- =====================================================================
-- STYLEME · 01 · ESQUEMA DE LA BASE DE DATOS
-- PostgreSQL 17 + pgvector
--
-- Crea las 16 tablas del modelo (docs/planeacion/15-modelo-de-datos.md).
-- Diagrama: docs/diagramas/entidad-relacion.dbml
--
-- Se ejecuta solo, la primera vez que Docker crea la base.
-- Para repetirlo: docker compose down -v && docker compose up -d
--
-- ORDEN: una tabla solo puede apuntar (REFERENCES) a tablas que ya existen,
-- por eso se crean de las más simples a las que dependen de otras.
--
-- GENERATED BY DEFAULT AS IDENTITY: el id se genera solo, pero los datos
-- iniciales (03-datos-iniciales.sql) pueden escribir un id fijo si hace falta.
-- =====================================================================

-- Extensión que agrega el tipo VECTOR y la búsqueda por similitud
CREATE EXTENSION IF NOT EXISTS vector;


-- =====================================================================
-- GRUPO 1 · CATÁLOGO
-- =====================================================================

-- Ropa, maquillaje, skincare, capilar (D-004)
CREATE TABLE categoria (
    id      SMALLINT    GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug    VARCHAR(20) NOT NULL UNIQUE,
    nombre  VARCHAR(40) NOT NULL
);

-- Zonas de Bucaramanga (Cabecera, Sur, La Aurora...)
CREATE TABLE zona (
    id      SMALLINT    GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre  VARCHAR(60) NOT NULL UNIQUE
);

-- Va antes que tienda porque tienda.comerciante_id apunta aquí.
-- Ley 1581: solo datos mínimos. La contraseña se guarda cifrada con BCrypt.
CREATE TABLE usuario (
    id               BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre           VARCHAR(80)  NOT NULL,
    correo           VARCHAR(120) NOT NULL UNIQUE,
    contrasena_hash  VARCHAR(100) NOT NULL,
    rol              VARCHAR(15)  NOT NULL DEFAULT 'COMPRADOR'
                     CHECK (rol IN ('COMPRADOR', 'COMERCIANTE', 'ADMIN')),
    activo           BOOLEAN      NOT NULL DEFAULT true,
    fecha_registro   TIMESTAMP    NOT NULL DEFAULT now()
);

-- "No se sabe" = NULL (zona, coordenadas, horario). Sin coordenadas no sale en el mapa.
CREATE TABLE tienda (
    id                      BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug                    VARCHAR(60)  NOT NULL UNIQUE,
    nombre                  VARCHAR(100) NOT NULL,
    descripcion             VARCHAR(500),
    categoria_principal_id  SMALLINT     NOT NULL REFERENCES categoria (id),
    zona_id                 SMALLINT     REFERENCES zona (id),
    direccion               VARCHAR(150),
    lat                     NUMERIC(9,6) CHECK (lat BETWEEN -90 AND 90),
    lng                     NUMERIC(9,6) CHECK (lng BETWEEN -180 AND 180),
    horario                 VARCHAR(120),
    whatsapp                VARCHAR(15)  CHECK (whatsapp ~ '^[0-9]+$'),
    telefono                VARCHAR(15)  CHECK (telefono ~ '^[0-9]+$'),
    instagram               VARCHAR(60),
    web                     VARCHAR(150),
    foto                    VARCHAR(255),
    verificado              BOOLEAN      NOT NULL DEFAULT false,
    activa                  BOOLEAN      NOT NULL DEFAULT true,
    comerciante_id          BIGINT       REFERENCES usuario (id),
    fecha_registro          TIMESTAMP    NOT NULL DEFAULT now(),
    -- Las coordenadas van juntas: o están las dos o ninguna
    CONSTRAINT tienda_coordenadas_completas CHECK ((lat IS NULL) = (lng IS NULL))
);

-- Precio en pesos, sin decimales; NULL si no se sabe.
-- tipo_prenda y foto_probador solo se usan en ropa.
CREATE TABLE producto (
    id                   BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    codigo               VARCHAR(10)  NOT NULL UNIQUE,
    tienda_id            BIGINT       NOT NULL REFERENCES tienda (id),
    categoria_id         SMALLINT     NOT NULL REFERENCES categoria (id),
    nombre               VARCHAR(150) NOT NULL,
    marca                VARCHAR(80),
    precio               INTEGER      CHECK (precio > 0),
    descripcion          VARCHAR(500),
    foto                 VARCHAR(500),
    fuente               VARCHAR(500),
    fuente_ingredientes  VARCHAR(500),
    tipo_prenda          VARCHAR(10)  CHECK (tipo_prenda IN ('superior', 'inferior', 'completa')),
    foto_probador        VARCHAR(255),
    es_ejemplo           BOOLEAN      NOT NULL DEFAULT false,
    activo               BOOLEAN      NOT NULL DEFAULT true,
    fecha_registro       TIMESTAMP    NOT NULL DEFAULT now()
);

-- Cada ingrediente se escribe una sola vez (nombre INCI)
CREATE TABLE ingrediente (
    id      BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nombre  VARCHAR(120) NOT NULL UNIQUE
);

-- Muchos a muchos: la llave es la PAREJA (producto, ingrediente).
-- ON DELETE CASCADE: si se borra el producto, se borran sus filas aquí.
CREATE TABLE producto_ingrediente (
    producto_id     BIGINT   NOT NULL REFERENCES producto (id) ON DELETE CASCADE,
    ingrediente_id  BIGINT   NOT NULL REFERENCES ingrediente (id),
    orden           SMALLINT NOT NULL CHECK (orden > 0),
    PRIMARY KEY (producto_id, ingrediente_id)
);

-- Una sola tabla para 6 listas distintas: (grupo, valor)
CREATE TABLE etiqueta (
    id     SMALLINT    GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    grupo  VARCHAR(15) NOT NULL
           CHECK (grupo IN ('paso', 'tipo_piel', 'tipo_cabello', 'cuero', 'objetivo', 'libre_de')),
    valor  VARCHAR(30) NOT NULL,
    CONSTRAINT etiqueta_unica UNIQUE (grupo, valor)
);

CREATE TABLE producto_etiqueta (
    producto_id  BIGINT   NOT NULL REFERENCES producto (id) ON DELETE CASCADE,
    etiqueta_id  SMALLINT NOT NULL REFERENCES etiqueta (id),
    PRIMARY KEY (producto_id, etiqueta_id)
);


-- =====================================================================
-- GRUPO 2 · COMUNIDAD
-- =====================================================================

-- Una reseña es de UNA tienda o de UN producto, nunca de los dos ni de ninguno.
-- (a IS NULL) <> (b IS NULL) es verdadero solo cuando exactamente uno está lleno.
-- Los UNIQUE impiden reseñar dos veces lo mismo; en PostgreSQL los NULL
-- no chocan entre sí, por eso las dos reglas conviven sin problema.
CREATE TABLE resena (
    id           BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id   BIGINT       NOT NULL REFERENCES usuario (id),
    tienda_id    BIGINT       REFERENCES tienda (id) ON DELETE CASCADE,
    producto_id  BIGINT       REFERENCES producto (id) ON DELETE CASCADE,
    corazones    SMALLINT     NOT NULL CHECK (corazones BETWEEN 1 AND 5),
    comentario   VARCHAR(500),
    estado       VARCHAR(10)  NOT NULL DEFAULT 'PENDIENTE'
                 CHECK (estado IN ('PENDIENTE', 'PUBLICADA', 'RECHAZADA')),
    fecha        TIMESTAMP    NOT NULL DEFAULT now(),
    CONSTRAINT resena_una_de_dos CHECK ((tienda_id IS NULL) <> (producto_id IS NULL)),
    CONSTRAINT resena_unica_tienda   UNIQUE (usuario_id, tienda_id),
    CONSTRAINT resena_unica_producto UNIQUE (usuario_id, producto_id)
);

-- Mismas reglas que resena: favorito de UNA tienda o de UN producto
CREATE TABLE favorito (
    id           BIGINT    GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    usuario_id   BIGINT    NOT NULL REFERENCES usuario (id),
    tienda_id    BIGINT    REFERENCES tienda (id) ON DELETE CASCADE,
    producto_id  BIGINT    REFERENCES producto (id) ON DELETE CASCADE,
    fecha        TIMESTAMP NOT NULL DEFAULT now(),
    CONSTRAINT favorito_uno_de_dos CHECK ((tienda_id IS NULL) <> (producto_id IS NULL)),
    CONSTRAINT favorito_unico_tienda   UNIQUE (usuario_id, tienda_id),
    CONSTRAINT favorito_unico_producto UNIQUE (usuario_id, producto_id)
);


-- =====================================================================
-- GRUPO 3 · ANÁLISIS DE DATOS
-- =====================================================================

-- Cada acción en la página. Base de los indicadores del informe.
-- ON DELETE SET NULL: si se borra una tienda o un producto, el evento
-- se conserva (cuenta para las estadísticas) pero sin la referencia.
CREATE TABLE evento (
    id                   BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tipo                 VARCHAR(25)  NOT NULL CHECK (tipo IN (
                             'VER_TIENDA', 'VER_PRODUCTO', 'CLIC_WHATSAPP', 'CLIC_COMO_LLEGAR',
                             'BUSQUEDA', 'FILTRAR_CATEGORIA', 'USAR_PROBADOR',
                             'USAR_RECOMENDADOR', 'ARMAR_SALIDA', 'ABRIR_LIA')),
    sesion_id            VARCHAR(36)  NOT NULL,
    usuario_id           BIGINT       REFERENCES usuario (id) ON DELETE SET NULL,
    tienda_id            BIGINT       REFERENCES tienda (id) ON DELETE SET NULL,
    producto_id          BIGINT       REFERENCES producto (id) ON DELETE SET NULL,
    categoria_id         SMALLINT     REFERENCES categoria (id),
    texto_busqueda       VARCHAR(100),
    cantidad_resultados  INTEGER      CHECK (cantidad_resultados >= 0),
    dispositivo          VARCHAR(10)  CHECK (dispositivo IN ('celular', 'computador')),
    detalle              JSONB,
    fecha_hora           TIMESTAMP    NOT NULL DEFAULT now()
);

-- Un resumen por conversación con Lía. NO se guarda lo que escribe la persona (D-053).
CREATE TABLE conversacion_lia (
    id                    BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sesion_id             VARCHAR(36)  NOT NULL,
    usuario_id            BIGINT       REFERENCES usuario (id) ON DELETE SET NULL,
    tema                  VARCHAR(12)  NOT NULL
                          CHECK (tema IN ('catalogo', 'general', 'social', 'aclaracion')),
    categoria_id          SMALLINT     REFERENCES categoria (id),
    sentimiento_final     VARCHAR(10)  CHECK (sentimiento_final IN ('positivo', 'negativo', 'neutral')),
    cantidad_mensajes     SMALLINT     NOT NULL CHECK (cantidad_mensajes > 0),
    modo                  VARCHAR(6)   NOT NULL CHECK (modo IN ('IA', 'PLAN_B', 'MIXTO')),
    similitud_promedio    NUMERIC(4,3) CHECK (similitud_promedio BETWEEN 0 AND 1),
    latencia_promedio_ms  INTEGER      CHECK (latencia_promedio_ms >= 0),
    tokens_entrada        INTEGER      CHECK (tokens_entrada >= 0),
    tokens_salida         INTEGER      CHECK (tokens_salida >= 0),
    inicio                TIMESTAMP    NOT NULL,
    fin                   TIMESTAMP,
    CONSTRAINT conversacion_fechas CHECK (fin IS NULL OR fin >= inicio)
);

-- Qué productos recomendó Lía en cada conversación, y cuántas veces
CREATE TABLE lia_recomendacion (
    conversacion_id  BIGINT   NOT NULL REFERENCES conversacion_lia (id) ON DELETE CASCADE,
    producto_id      BIGINT   NOT NULL REFERENCES producto (id) ON DELETE CASCADE,
    veces            SMALLINT NOT NULL DEFAULT 1 CHECK (veces > 0),
    PRIMARY KEY (conversacion_id, producto_id)
);


-- =====================================================================
-- GRUPO 4 · INTELIGENCIA ARTIFICIAL (RAG)
-- =====================================================================

-- VECTOR(768): 768 números que representan el significado del texto
-- (mismo tamaño que pide el backend a gemini-embedding-001).
-- Un fragmento habla de una tienda, de un producto o de una guía:
-- el CHECK obliga a que las llaves coincidan con tipo_fuente.
-- El índice HNSW de "embedding" va en 02-indices.sql.
CREATE TABLE fragmento_conocimiento (
    id                BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tipo_fuente       VARCHAR(10)  NOT NULL CHECK (tipo_fuente IN ('tienda', 'producto', 'guia')),
    tienda_id         BIGINT       REFERENCES tienda (id) ON DELETE CASCADE,
    producto_id       BIGINT       REFERENCES producto (id) ON DELETE CASCADE,
    titulo            VARCHAR(150) NOT NULL,
    texto             TEXT         NOT NULL,
    hash_texto        CHAR(64)     NOT NULL,
    embedding         VECTOR(768)  NOT NULL,
    modelo_embedding  VARCHAR(40)  NOT NULL,
    actualizado       TIMESTAMP    NOT NULL DEFAULT now(),
    CONSTRAINT fragmento_fuente_coherente CHECK (
        (tipo_fuente = 'tienda'   AND tienda_id IS NOT NULL AND producto_id IS NULL) OR
        (tipo_fuente = 'producto' AND producto_id IS NOT NULL AND tienda_id IS NULL) OR
        (tipo_fuente = 'guia'     AND tienda_id IS NULL AND producto_id IS NULL)
    )
);

-- Una fila por pregunta en cada ejecución de la evaluación de IA (rama test/evaluacion-ia)
CREATE TABLE evaluacion_ia (
    id               BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ejecucion        VARCHAR(36)  NOT NULL,
    pregunta         VARCHAR(300) NOT NULL,
    tipo_pregunta    VARCHAR(12)  NOT NULL
                     CHECK (tipo_pregunta IN ('catalogo', 'fuera_tema', 'salud', 'ambigua', 'general')),
    esperado         JSONB        NOT NULL,
    obtenido         JSONB        NOT NULL,
    precision_k      NUMERIC(4,3) CHECK (precision_k BETWEEN 0 AND 1),
    recall_k         NUMERIC(4,3) CHECK (recall_k BETWEEN 0 AND 1),
    sin_alucinacion  BOOLEAN      NOT NULL,
    aprobada         BOOLEAN      NOT NULL,
    latencia_ms      INTEGER      CHECK (latencia_ms >= 0),
    fecha            TIMESTAMP    NOT NULL DEFAULT now()
);
